import {esc,uid} from './text.js';
import {languages,trims,designs,authorVoices,localeOf,trimOf,wordBand,creativityLabel,sampleFor,imprintOf,designOf} from './book.js';
export const wizardSteps=['Language & genre','Book design','Title pages','Length & chapters','Voice & references','Story world','Review brief','Outline & cast'];
export const genres=['Literary fiction','Contemporary fiction','Mystery','Fantasy','Science fiction','Romance','Memoir','Creative nonfiction','Poetry','Academic nonfiction','Children’s fiction','Custom'];
export function newWizard(settings){const base={flowVersion:2,step:0,language:'English',customLanguage:'',genre:'Literary fiction',customGenre:'',audience:'Adults',direction:'auto',trim:'Trade paperback',customTrim:{width:5.5,height:8.5},publicationStyle:'Modern literary',customDesign:{font:'Georgia,serif',size:11,leading:1.65,align:'center',accent:'#334e40'},imprintChoice:'BookWiz Editions',imprintName:'BookWiz Editions',title:'',subtitle:'',author:settings.author||settings.name||'',target:65000,chapterCount:12,style:'Restrained literary',authorStyle:'Original voice',customAuthor:'',pov:'Close third person',tense:'Past',creativity:50,styleNotes:'',premise:'',world:'',characters:[],bible:[],references:[],frontMatter:{halfTitle:true,contents:true,includePreface:true,dedication:'',edition:''},color:'sea'};const d=settings.bookDefaults||{};return {...base,...d,frontMatter:{...base.frontMatter,...d.frontMatter},title:'',subtitle:'',premise:'',world:'',characters:[],bible:[],references:[],author:settings.author||settings.name||'',profileAuthor:settings.author||settings.name||'',authorFollowsProfile:true,rememberChoices:settings.rememberBookDefaults!==false};}
export function syncWizard(form,w){if(!form)return;const d=Object.fromEntries(new FormData(form));for(const[k,v]of Object.entries(d)){if(k.startsWith('character_')){const m=k.match(/^character_(\d+)_(.+)$/);if(m&&w.characters[Number(m[1])])w.characters[Number(m[1])][m[2]]=v;continue;}if(k.startsWith('front_')){w.frontMatter[k.slice(6)]=v;continue;}if(k.startsWith('trim_')){w.customTrim[k.slice(5)]=Number(v);continue;}if(k.startsWith('design_')){w.customDesign[k.slice(7)]=['size','leading'].includes(k.slice(7))?Number(v):v;continue;}w[k]=['target','chapterCount','creativity'].includes(k)?Number(v):v;}for(const k of ['halfTitle','contents','includePreface'])if(form.elements.namedItem('front_'+k))w.frontMatter[k]=form.elements.namedItem('front_'+k).checked;w.frontMatter.dedication=d.front_dedication??w.frontMatter.dedication;if(w.imprintChoice!=='Custom')w.imprintName=w.imprintChoice==='Author’s imprint'?w.author||'':w.imprintChoice;if(d.targetNumber!==undefined)w.target=Number(d.targetNumber);if(d.chapterCountNumber!==undefined)w.chapterCount=Number(d.chapterCountNumber);w.target=Math.max(500,Math.min(300000,w.target));w.chapterCount=Math.max(1,Math.min(60,w.chapterCount));refreshCharacterSummaries(form,w);}
export function wizardBook(w){return {...w,language:w.language==='Custom'?w.customLanguage||'Custom':w.language,genre:w.genre==='Custom'?w.customGenre||'Custom':w.genre,imprint:w.imprintName,chapters:Array.from({length:w.chapterCount},(_,i)=>({id:'preview-'+i,title:localeOf(w).chapter+' '+(i+1),beat:'',text:''}))};}
const opts=(items,value)=>items.map(item=>`<option value="${esc(item)}" ${item===value?'selected':''}>${esc(item)}</option>`).join('');
function select(label,name,items,value,help=''){return `<label class="field"><span>${label}</span><select name="${name}">${opts(items,value)}</select>${help?`<small>${help}</small>`:''}</label>`;}
function input(label,name,value,extra=''){return `<label class="field"><span>${label}</span><input name="${name}" value="${esc(value)}" ${extra}></label>`;}
function textarea(label,name,value,help='',extra=''){return `<label class="field full"><span>${label}</span><textarea name="${name}" rows="4" ${extra}>${esc(value)}</textarea>${help?`<small>${help}</small>`:''}</label>`;}
export function wizardAside(w,I,B){const p=wizardBook(w),l=localeOf(p),d=designOf(p),[width,height]=trimOf(p);return `<aside class="creation-aside"><div class="row between"><span class="small">Your book, taking shape</span><span class="badge">${esc(w.language==='Custom'?w.customLanguage:w.language)}</span></div><div class="mini-book-page" dir="${l.dir}" lang="${l.code}" style="aspect-ratio:${width}/${height};font-family:${esc(d.font)}"><div class="mini-imprint">${esc(imprintOf(p))}</div><h3>${esc(w.title||l.title)}</h3>${w.subtitle?`<p class="mini-subtitle">${esc(w.subtitle)}</p>`:''}<p class="mini-author">${esc(w.author||'')}</p><div class="mini-divider"></div><p class="mini-prose">${esc(sampleFor(p))}</p></div><div class="row between small muted"><span>${width} × ${height} in</span><span>${esc(w.publicationStyle)}</span></div><p class="creation-sample-note">${w.prosePreview?.cached?'Saved prose preview, reused on this device.':w.prosePreview?'AI prose preview from your selected model.':'Original language sample. Use a prose preview to hear your exact brief.'}</p><div class="row wrap gap8">${B('wizard-preview','Preview pages','book','secondary','type="button"')}${B('wizard-prose-preview','Preview prose','feather','quiet','type="button"')}${w.prosePreview?B('refresh-prose-preview','Refresh','','quiet','type="button"'):''}</div>${w.modelRecoveries?.length?B('setup-recovery','View saved suggestion replies','note','quiet','type="button"'):''}<div class="creation-private">${I('lock')}Saved here. Shared with your model only after approval.</div></aside>`;}
export function reviewBrief(w,B){const p=wizardBook(w);const rows=[['Language & genre',`${p.language} · ${p.genre} · ${p.audience}`,0],['Book design',`${trimOf(p).join(' × ')} in · ${p.publicationStyle} · ${imprintOf(p)}`,1],['Title & author',`${p.title} · ${p.author}`,2],['Length',`${p.target.toLocaleString()} words · ${p.chapterCount} chapters · ${wordBand(p.target)}`,3],['Voice',`${p.style} · ${p.authorStyle} · ${creativityLabel(p.creativity)} · ${p.pov}`,4],['The premise',p.premise,5]];return `<div class="brief-review">${rows.map(([label,value,step])=>`<div><span>${label}</span><p>${esc(value)}</p>${B('wizard-jump','Edit','','quiet',`data-index="${step}" type="button"`)}</div>`).join('')}<div><span>Optional story notes</span><p>${p.characters.filter(c=>c.name).length} character sheets · ${p.world?'Setting supplied':'Setting will be generated'} · ${p.references.length} reference(s)</p></div><div><span>Opening pages</span><p>${p.frontMatter.halfTitle?'Half title · ':''}Title · Publication page · ${p.frontMatter.dedication?'Dedication · ':''}${p.frontMatter.contents?'Contents · ':''}${p.frontMatter.includePreface?'Preface':''}</p></div></div>`;}
// Model replies sometimes include a standalone heading despite the plain-text prompt.
// Only clean suggestions; never normalize an author's saved or typed manuscript.
export function cleanPremiseSuggestion(value){return String(value??'').replace(/^\s*(?:#{1,6}[ \t]+Premise[ \t]*:?|\*\*Premise:?\*\*:?)\s*\n+/i,'').trim();}
const characterNotes=[['wound','Inner wound','What past experience still shapes their choices?'],['desire','Conscious desire','What do they believe they want?'],['need','Subconscious need','What do they need to learn or accept?'],['contradiction','Contradiction','Where do their actions and beliefs pull apart?'],['voice','Voice cadence','How do their rhythm, vocabulary and silences sound?']];
function refreshCharacterSummaries(form,w){form.querySelectorAll('.character-sheet').forEach((sheet,i)=>{const c=w.characters[i];if(!c)return;const name=sheet.querySelector('.character-sheet-name-text'),role=sheet.querySelector('.character-sheet-name>small'),notes=sheet.querySelector('.character-sheet-notes');if(name)name.textContent=c.name||'New character';if(role)role.textContent=c.role||'Character sheet';if(notes)notes.textContent=characterNotes.filter(([key])=>String(c[key]||'').trim()).length+' of '+characterNotes.length+' story notes';});}
function characterNoteField(c,index,key,label,help){return `<label class="field ${key==='voice'?'full':''}"><span>${label}</span><textarea name="character_${index}_${key}" rows="3" maxlength="3000">${esc(c[key]||'')}</textarea><small>${help}</small></label>`;}
export function storyWorldFields(w,I,B){return `<div class="story-brief">
<section class="story-brief-section story-premise" aria-labelledby="premise-heading"><div class="story-section-heading"><div><h2 id="premise-heading">The premise</h2><p>Who wants what, what stands in their way, and what will it cost?</p></div></div><label class="field"><span class="story-field-label">Your story in a few sentences</span><textarea name="premise" rows="6" required maxlength="12000">${esc(w.premise)}</textarea></label><div class="story-suggestion-actions">${B('suggest-premise','Suggest an idea','feather','secondary','type="button"')}${B('refine-premise','Refine my premise','pen','secondary','type="button"')}</div></section>
<section class="story-brief-section story-setting" aria-labelledby="world-heading"><div class="story-section-heading"><div><h2 id="world-heading">World &amp; setting <span>Optional</span></h2><p>Give the story a place to stand: its time, atmosphere, rules and tensions.</p></div></div><label class="field"><span class="story-field-label">The world around your characters</span><textarea name="world" rows="5" maxlength="16000" aria-describedby="world-help">${esc(w.world)}</textarea><small id="world-help">Keep the details that matter. You can leave this open and build it with the outline.</small></label></section>
<section class="story-brief-section story-cast" aria-labelledby="cast-heading"><div class="story-section-heading"><div><h2 id="cast-heading">Character sheets <span>Optional</span></h2><p>${w.characters.length?'Open a sheet to shape their motives and voice.':'Start with a name. Motives and voice can take shape as you go.'}</p></div>${B('wizard-add-character','Add a character','users','secondary','type="button"')}</div><div class="story-character-list">${w.characters.map((c,i)=>{const filled=characterNotes.filter(([key])=>String(c[key]||'').trim()).length;return `<details class="character-sheet" ${i===0||!c.name?'open':''}><summary><span class="character-sheet-name"><span class="character-sheet-name-text">${esc(c.name||'New character')}</span><small>${esc(c.role||'Character sheet')}</small></span><span class="character-sheet-notes">${filled} of ${characterNotes.length} story notes</span><span class="character-sheet-chevron">${I('chevron')}</span></summary><div class="character-sheet-body"><div class="form-grid character-identity">${input('Name',`character_${i}_name`,c.name,'maxlength="100" autocomplete="off"')}${input('Role in the story',`character_${i}_role`,c.role||'','maxlength="100" autocomplete="off"')}</div><fieldset class="character-note-group"><legend>What drives them</legend><div class="form-grid">${characterNotes.slice(0,4).map(([key,label,help])=>characterNoteField(c,i,key,label,help)).join('')}</div></fieldset><fieldset class="character-note-group"><legend>How they sound</legend>${characterNoteField(c,i,...characterNotes[4])}</fieldset><div class="character-sheet-actions">${B('wizard-remove-character','Remove character','trash','quiet',`type="button" data-index="${i}"`)}</div></div></details>`;}).join('')}</div><div class="story-suggestion-actions">${B('suggest-world','Suggest a world & cast','world','secondary','type="button"')}</div><p class="story-suggestion-note">Suggestions use your premise and earlier choices. Review and edit them here before continuing. Anything left open can be developed with the outline.</p></section></div>`;}
export function renderWizard(w,{I,B,connection,busy,project}){if(!w)return '';const step=w.step;let content='';
if(step===0)content=`<div class="form-grid">${select('Book language','language',[...Object.keys(languages),'Custom'],w.language)}${w.language==='Custom'?input('Custom language','customLanguage',w.customLanguage,'required maxlength="80"'):select('Text direction','direction',['auto','ltr','rtl'],w.direction)}${select('Genre','genre',genres,w.genre)}${w.genre==='Custom'?input('Custom genre','customGenre',w.customGenre,'required maxlength="100"'):select('Intended readers','audience',['Adults','Young adults','Middle grade','Children','Academic / professional'],w.audience)}<div class="field full"><span>A language with a life of its own.</span><p class="small muted">Titles, character sheets, the preface, and generated chapters follow this choice. You can keep your own names and terminology in the style notes.</p></div></div>`;
if(step===1)content=`<div class="form-grid">${select('Book format','trim',[...Object.keys(trims),'Custom'],w.trim)}${select('Publication aesthetic','publicationStyle',Object.keys(designs),w.publicationStyle)}${w.trim==='Custom'?`${input('Width · inches','trim_width',w.customTrim.width,'type="number" min="3" max="14" step="0.01" required')}${input('Height · inches','trim_height',w.customTrim.height,'type="number" min="3" max="14" step="0.01" required')}`:''}${select('Imprint','imprintChoice',['BookWiz Editions','Author’s imprint','Private edition','Custom'],w.imprintChoice)}${input('Imprint name','imprintName',w.imprintName,'required maxlength="100"')}<p class="full small muted">${designs[w.publicationStyle].note} Original design traditions, without borrowed publisher branding.</p>${w.publicationStyle==='Custom'?`${select('Book typeface','design_font',['Georgia,serif','Palatino,"Book Antiqua",serif','"Times New Roman",serif','Arial,sans-serif'],w.customDesign.font)}${select('Chapter alignment','design_align',['center','left'],w.customDesign.align)}${input('Type size · points','design_size',w.customDesign.size,'type="number" min="9" max="15" step="0.5" required')}${input('Line spacing','design_leading',w.customDesign.leading,'type="number" min="1.35" max="2" step="0.05" required')}${input('Accent color','design_accent',w.customDesign.accent,'type="color"')}`:''}<div class="full">${B('wizard-preview','See this exact page design','book','secondary','type="button"')}</div></div>`;
if(step===2)content=`<div class="form-grid">${input('Book name','title',w.title,'required maxlength="120"')}${input('Author’s name','author',w.author,'required maxlength="100"')}<div class="full"><p class="small muted">${w.authorFollowsProfile?'Your saved author name is filled in.':'An author name for this book.'} ${w.profileAuthor&&w.author!==w.profileAuthor?B('wizard-use-author','Use saved author','','quiet','type="button"'):''}</p></div><div class="full">${input('Subtitle · optional','subtitle',w.subtitle,'maxlength="130"')}</div><div class="front-options full">${[['halfTitle','Half-title page'],['contents','Contents page'],['includePreface','Generate a preface']].map(([name,label])=>`<label><input type="checkbox" name="front_${name}" ${w.frontMatter[name]?'checked':''}><span>${label}</span></label>`).join('')}</div>${textarea('Dedication · optional','front_dedication',w.frontMatter.dedication,'A person, a place, a few words that belong at the beginning.','maxlength="3000"')}<p class="full small muted">The publication page includes your copyright, imprint, edition, and github.com/muneebwanee/BookWizOfficial. That project link is not an ISBN.</p><div class="full">${B('wizard-preview','Preview opening pages','book','secondary','type="button"')}</div></div>`;
if(step===3)content=`<div class="range-card"><label for="target-range">Target word count</label><div class="range-value"><output id="target-output">${w.target.toLocaleString()}</output><span id="word-band">${wordBand(w.target)}</span></div><input id="target-range" name="target" type="range" min="500" max="300000" step="500" value="${w.target}"><div class="range-labels"><span>Short story</span><span>Novella</span><span>Novel</span><span>Epic</span></div>${input('Exact word target','targetNumber',w.target,'type="number" min="500" max="300000" step="500" required')}<p>Short story: under 7,500 · Novelette: 7,500–17,500 · Novella: 17,500–40,000 · Novel: 40,000+. These are guides; conventions vary by genre.</p></div><div class="range-card"><label for="chapter-range">Planned chapters</label><div class="range-value"><output id="chapter-output">${w.chapterCount}</output><span id="chapter-average">About ${Math.round(w.target/w.chapterCount).toLocaleString()} words per chapter</span></div><input id="chapter-range" name="chapterCount" type="range" min="1" max="60" step="1" value="${w.chapterCount}"><div class="range-labels"><span>One sustained work</span><span>A broader arc</span></div>${input('Exact chapter count','chapterCountNumber',w.chapterCount,'type="number" min="1" max="60" required')}</div>`;
if(step===4)content=`<div class="form-grid">${select('Writing voice','style',['Restrained literary','Lyrical','Classic wit','Clear & direct','Custom'],w.style)}${select('Author influence','authorStyle',Object.keys(authorVoices),w.authorStyle)}${w.authorStyle==='Custom'?`<div class="full">${input('Custom author or influence','customAuthor',w.customAuthor,'required maxlength="200"')}</div>`:''}${select('Point of view','pov',['Close third person','First person','Omniscient','Second person','Custom / mixed'],w.pov)}${select('Tense','tense',['Past','Present','Custom / mixed'],w.tense)}<div class="range-card full"><label for="creativity-range">Creativity</label><div class="range-value"><output id="creativity-output">${w.creativity}</output><span id="creativity-label">${creativityLabel(w.creativity)}</span></div><input id="creativity-range" name="creativity" type="range" min="0" max="100" step="5" value="${w.creativity}"><div class="range-labels"><span>Grounded</span><span>Balanced</span><span>Daring</span></div><p>The imaginative range changes. Established story facts stay anchored.</p></div>${textarea('Your style notes','styleNotes',w.styleNotes,'Name the cadence, imagery, influences, boundaries, and details that matter to you. Author influence guides craft; every passage remains original.','maxlength="12000"')}<div class="field full"><span>Reference material · optional</span><input id="reference-upload" type="file" accept=".txt,.md,.pdf" aria-label="Upload optional reference material"><small id="reference-status">${w.references.map((r,i)=>`${esc(r.name)} ${B('remove-reference','Remove','','quiet',`type="button" data-index="${i}"`)}`).join('<br>')||'Text, Markdown, or text-based PDF up to 10 MB. First 150 PDF pages parsed locally.'}</small><small>AI context uses at most 12,000 reference characters, around 3,000 tokens. Short excerpts help on free tiers. Scanned PDFs need OCR first.</small></div></div>`;
if(step===5)content=storyWorldFields(w,I,B);
if(step===6)content=reviewBrief(w,B)+`<label class="check-row" style="margin-top:24px"><input name="rememberChoices" type="checkbox" ${w.rememberChoices!==false?'checked':''}><span>Remember these choices for the next book</span></label>`+`<div class="notice" style="margin-top:24px">Next, your chosen model creates the chapter outline, a style guide, the missing world details and characters, and your selected preface. You review and edit them before drafting begins.</div>`;
if(step===7){const p=project;content=p?`<div class="outline-status ${busy?'working':''}">${I(busy?'pen':'check')}<div><h3>${busy?'Building your story’s architecture…':p.outlineReady?'Your book has a shape.':'Your brief is safely kept.'}</h3><p>${busy?'The model is shaping chapters, characters, world details and opening pages.':p.outlineReady?'Edit the plan, explore the cast, and continue when it feels right.':'Generate or retry the outline when your connection is ready.'}</p></div></div>${p.outlineError?`<div class="notice warning" role="alert">${esc(p.outlineError)}${p.outlineWork?.recoveries?.length?B('outline-recovery','View saved responses','','quiet','type="button"'):''}</div>`:''}${!p.outlineReady&&!busy?B('generate-outline','Generate the outline','list','primary'):''}${p.outlineReady?`<div class="outline-editors">${p.chapters.map((c,i)=>`<details class="chapter-plan" ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')}</span>${esc(c.title)}</summary><label class="field"><span>Chapter title</span><input class="outline-title" data-index="${i}" value="${esc(c.title)}" maxlength="150"></label><label class="field"><span>Beat & consequence</span><textarea class="beat-input" data-index="${i}" rows="4">${esc(c.beat)}</textarea></label></details>`).join('')}</div><div class="outline-people"><h3>${p.characters.length} characters · ${p.bible.length} world details</h3><p>${esc(p.world)}</p><div class="row wrap gap8">${B('wizard-edit-cast','Edit characters','users','secondary')}${B('wizard-edit-world','Edit world bible','world','secondary')}${B('wizard-preview','Preview the book','book','secondary')}</div></div>`:''}`:'';}
const titles=['First, a language.','Give the book a form.','Put your name on the page.','Make room for the story.','Find the voice.','A world begins with a premise.','Everything, before the first draft.','The shape of what comes next.'];return `<div class="page creation-page"><div class="page-intro"><div><h1>${titles[step]}</h1><p>${step===7?'An outline is a conversation with the book you want to write.':'One considered choice at a time. Your brief stays on this device.'}</p></div>${B('cancel-wizard','Save & close','','quiet')}</div><div class="creation-progress" role="navigation" aria-label="Book setup steps">${wizardSteps.map((title,i)=>`<button class="${step===i?'active':i<step?'complete':''}" data-action="wizard-jump" data-index="${i}" ${i>step||step===7?'disabled':''} aria-current="${step===i?'step':'false'}"><span>${i<step?I('check'):i+1}</span><strong>${title}</strong></button>`).join('')}</div><div class="creation-layout"><form id="wizard-form" class="creation-form"><div class="selected-model row between"><span class="row gap8">${I('cpu')}${esc(connection?.name||'Choose a text model')}</span>${B('wizard-model','Switch model','','quiet','type="button"')}</div>${content}<div class="form-actions">${B(step&&step<7?'wizard-back':'cancel-wizard',step&&step<7?'Back':'Save & close','','quiet','type="button"')}${step<6?B('wizard-next','Continue','arrow','primary','type="submit"'):step===6?B('create-project','Generate my outline','list','primary','type="submit"'):project?.outlineReady?B('accept-outline','Keep this plan & write','arrow','primary','type="submit"'):''}</div></form>${step<7?wizardAside(w,I,B):`<aside class="creation-aside"><img src="assets/story-architecture.svg" alt="Original vector book and chapter composition" class="creation-illustration"><h2>Room for every thread.</h2><p class="small muted">Your outline, character motives, world facts and style guide travel with each chapter request. Every draft stays editable.</p><div class="notice small">Review the plan first. Drafting can run in saved, resumable passes with a request limit you choose.</div></aside>`}</div></div>`;}
